BEGIN TRANSACTION;
CREATE TABLE allocations (
	allocation_id VARCHAR(24) NOT NULL, 
	employee_id VARCHAR(16) NOT NULL, 
	project_id VARCHAR(24) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	weekly_hours FLOAT NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	is_injected_anomaly BOOLEAN NOT NULL, 
	PRIMARY KEY (allocation_id), 
	CONSTRAINT ck_allocation_dates CHECK (end_date >= start_date), 
	CHECK (weekly_hours > 0 AND weekly_hours <= 80), 
	CONSTRAINT ck_allocation_status CHECK (status IN ('planned', 'active', 'completed', 'cancelled')), 
	FOREIGN KEY(employee_id) REFERENCES employees (employee_id), 
	FOREIGN KEY(project_id) REFERENCES projects (project_id)
);
CREATE TABLE anomaly_ground_truth (
	ground_truth_id VARCHAR(32) NOT NULL, 
	issue_type VARCHAR(40) NOT NULL, 
	entity_type VARCHAR(40) NOT NULL, 
	entity_id VARCHAR(64) NOT NULL, 
	expected_detection VARCHAR(240) NOT NULL, 
	ground_truth_label VARCHAR(20) NOT NULL, 
	details TEXT NOT NULL, 
	recorded_at DATE NOT NULL, 
	PRIMARY KEY (ground_truth_id), 
	CONSTRAINT ck_ground_truth_label CHECK (ground_truth_label IN ('anomaly', 'baseline'))
);
CREATE TABLE audit_events (
	audit_id VARCHAR(32) NOT NULL, 
	entity_type VARCHAR(40) NOT NULL, 
	entity_id VARCHAR(64) NOT NULL, 
	action VARCHAR(40) NOT NULL, 
	event_time DATETIME NOT NULL, 
	details TEXT NOT NULL, 
	PRIMARY KEY (audit_id)
);
CREATE TABLE availability (
	availability_id VARCHAR(40) NOT NULL, 
	employee_id VARCHAR(16) NOT NULL, 
	period_start DATE NOT NULL, 
	period_end DATE NOT NULL, 
	capacity_hours FLOAT NOT NULL, 
	leave_hours FLOAT NOT NULL, 
	PRIMARY KEY (availability_id), 
	CONSTRAINT uq_employee_availability UNIQUE (employee_id, period_start), 
	CONSTRAINT ck_availability_dates CHECK (period_end >= period_start), 
	CONSTRAINT ck_availability_capacity CHECK (capacity_hours >= 0), 
	CONSTRAINT ck_availability_leave CHECK (leave_hours >= 0 AND leave_hours <= capacity_hours), 
	FOREIGN KEY(employee_id) REFERENCES employees (employee_id)
);
CREATE TABLE demand_import_events (
	event_id VARCHAR(32) NOT NULL, 
	demand_id VARCHAR(64) NOT NULL, 
	source_reference VARCHAR(64) NOT NULL, 
	payload_hash VARCHAR(64) NOT NULL, 
	received_at DATETIME NOT NULL, 
	PRIMARY KEY (event_id), 
	FOREIGN KEY(demand_id) REFERENCES demand_plans (demand_id)
);
CREATE TABLE demand_plans (
	demand_id VARCHAR(64) NOT NULL, 
	project_id VARCHAR(24) NOT NULL, 
	role_id VARCHAR(24) NOT NULL, 
	skill_id VARCHAR(24) NOT NULL, 
	period_start DATE NOT NULL, 
	period_end DATE NOT NULL, 
	required_hours FLOAT NOT NULL, 
	required_headcount INTEGER NOT NULL, 
	required_proficiency INTEGER NOT NULL, 
	demand_type VARCHAR(16) NOT NULL, 
	instance_number INTEGER NOT NULL, 
	PRIMARY KEY (demand_id), 
	CONSTRAINT uq_demand_logical_instance UNIQUE (project_id, role_id, skill_id, period_start, instance_number), 
	CONSTRAINT ck_demand_dates CHECK (period_end >= period_start), 
	CONSTRAINT ck_demand_hours CHECK (required_hours > 0), 
	CONSTRAINT ck_demand_headcount CHECK (required_headcount > 0), 
	CONSTRAINT ck_demand_proficiency CHECK (required_proficiency BETWEEN 1 AND 5), 
	CONSTRAINT ck_demand_instance CHECK (instance_number >= 1), 
	CONSTRAINT ck_demand_type CHECK (demand_type IN ('planned', 'observed')), 
	FOREIGN KEY(project_id) REFERENCES projects (project_id), 
	FOREIGN KEY(role_id) REFERENCES roles (role_id), 
	FOREIGN KEY(skill_id) REFERENCES skills (skill_id)
);
CREATE TABLE employee_skills (
	employee_skill_id VARCHAR(40) NOT NULL, 
	employee_id VARCHAR(16) NOT NULL, 
	skill_id VARCHAR(24) NOT NULL, 
	proficiency INTEGER NOT NULL, 
	verified_on DATE NOT NULL, 
	expires_on DATE, 
	verification_status VARCHAR(16) NOT NULL, 
	PRIMARY KEY (employee_skill_id), 
	CONSTRAINT uq_employee_skill UNIQUE (employee_id, skill_id), 
	CONSTRAINT ck_employee_skill_level CHECK (proficiency BETWEEN 1 AND 5), 
	CONSTRAINT ck_employee_skill_status CHECK (verification_status IN ('verified', 'pending', 'expired')), 
	CONSTRAINT ck_employee_skill_dates CHECK (expires_on IS NULL OR expires_on >= verified_on), 
	FOREIGN KEY(employee_id) REFERENCES employees (employee_id), 
	FOREIGN KEY(skill_id) REFERENCES skills (skill_id)
);
CREATE TABLE employees (
	employee_id VARCHAR(16) NOT NULL, 
	full_name VARCHAR(120) NOT NULL, 
	role_id VARCHAR(24) NOT NULL, 
	hire_date DATE NOT NULL, 
	employment_type VARCHAR(16) NOT NULL, 
	weekly_hours FLOAT NOT NULL, 
	experience_years FLOAT NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	lifecycle_end DATE, 
	PRIMARY KEY (employee_id), 
	CONSTRAINT ck_employee_employment_type CHECK (employment_type IN ('full_time', 'part_time')), 
	CONSTRAINT ck_employee_status CHECK (status IN ('active', 'leave', 'inactive')), 
	CHECK (weekly_hours > 0 AND weekly_hours <= 60), 
	CHECK (experience_years >= 0), 
	CHECK (lifecycle_end IS NULL OR lifecycle_end >= hire_date), 
	FOREIGN KEY(role_id) REFERENCES roles (role_id)
);
CREATE TABLE gap_analyses (
	gap_id VARCHAR(48) NOT NULL, 
	demand_id VARCHAR(64) NOT NULL, 
	project_id VARCHAR(24) NOT NULL, 
	skill_id VARCHAR(24) NOT NULL, 
	role_id VARCHAR(24) NOT NULL, 
	gap_type VARCHAR(24) NOT NULL, 
	shortage INTEGER NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	analyzed_on DATE NOT NULL, 
	PRIMARY KEY (gap_id), 
	CONSTRAINT uq_gap_demand_type UNIQUE (demand_id, gap_type), 
	CONSTRAINT ck_gap_type CHECK (gap_type IN ('missing_skill', 'proficiency', 'stale_skill', 'capacity')), 
	CONSTRAINT ck_gap_shortage CHECK (shortage > 0), 
	CONSTRAINT ck_gap_status CHECK (status IN ('open', 'mitigated', 'closed')), 
	FOREIGN KEY(demand_id) REFERENCES demand_plans (demand_id), 
	FOREIGN KEY(project_id) REFERENCES projects (project_id), 
	FOREIGN KEY(skill_id) REFERENCES skills (skill_id), 
	FOREIGN KEY(role_id) REFERENCES roles (role_id)
);
CREATE TABLE projects (
	project_id VARCHAR(24) NOT NULL, 
	name VARCHAR(140) NOT NULL, 
	client VARCHAR(100) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	priority VARCHAR(12) NOT NULL, 
	PRIMARY KEY (project_id), 
	CONSTRAINT ck_project_dates CHECK (end_date >= start_date), 
	CONSTRAINT ck_project_status CHECK (status IN ('planned', 'active', 'completed', 'cancelled')), 
	CONSTRAINT ck_project_priority CHECK (priority IN ('low', 'medium', 'high', 'critical'))
);
CREATE TABLE role_skills (
	role_id VARCHAR(24) NOT NULL, 
	skill_id VARCHAR(24) NOT NULL, 
	target_proficiency INTEGER NOT NULL, 
	is_required BOOLEAN NOT NULL, 
	PRIMARY KEY (role_id, skill_id), 
	CONSTRAINT ck_role_skill_proficiency CHECK (target_proficiency BETWEEN 1 AND 5), 
	FOREIGN KEY(role_id) REFERENCES roles (role_id), 
	FOREIGN KEY(skill_id) REFERENCES skills (skill_id)
);
CREATE TABLE roles (
	role_id VARCHAR(24) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	family VARCHAR(80) NOT NULL, 
	description TEXT NOT NULL, 
	lifecycle_state VARCHAR(16) NOT NULL, 
	PRIMARY KEY (role_id), 
	CONSTRAINT ck_role_lifecycle CHECK (lifecycle_state IN ('active', 'retired')), 
	UNIQUE (name)
);
CREATE TABLE skills (
	skill_id VARCHAR(24) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	category VARCHAR(80) NOT NULL, 
	description TEXT NOT NULL, 
	lifecycle_state VARCHAR(16) NOT NULL, 
	PRIMARY KEY (skill_id), 
	CONSTRAINT ck_skill_lifecycle CHECK (lifecycle_state IN ('active', 'retired')), 
	UNIQUE (name)
);
CREATE TABLE trainings (
	training_id VARCHAR(24) NOT NULL, 
	employee_id VARCHAR(16) NOT NULL, 
	skill_id VARCHAR(24) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	hours FLOAT NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	PRIMARY KEY (training_id), 
	CONSTRAINT ck_training_dates CHECK (end_date >= start_date), 
	CONSTRAINT ck_training_hours CHECK (hours > 0), 
	CONSTRAINT ck_training_status CHECK (status IN ('planned', 'in_progress', 'completed', 'cancelled')), 
	FOREIGN KEY(employee_id) REFERENCES employees (employee_id), 
	FOREIGN KEY(skill_id) REFERENCES skills (skill_id)
);
COMMIT;
